
class Event(object):
    def __eq__(self, other):
        return isinstance(other, self.__class__)

    def __hash__(self):
        return hash(self.__class__.__name__)


class Teardown(Event):
    def __init__(self, result):
        self._result = result

    def result(self):
        return self._result


class RetryContextFailed(Event):
    pass
